/**
 * SABIL SHIPMENT HAIL — Arrival Intake, Unit A1 (READ ONLY).
 * Adds lookup functions to the existing bound Google Apps Script project.
 * NEVER writes to any sheet, range, formula, timestamp or trigger.
 * Run inspectArrivalTicket, then enter the ticket number shown on the port document.
 * Separate names avoid collisions with Carrier Reports scripts.
 */
const ARRIVAL_A1 = Object.freeze({
  loading: 'Loading Register',
  offload: 'Offload Data',
  maxMatchesShown: 20
});

/** Interactive lookup; does not edit any worksheet. */
function inspectArrivalTicket() {
  const ui = SpreadsheetApp.getUi();
  const response = ui.prompt(
    'Arrival Intake — فحص تذكرة التحميل',
    'أدخل رقم تذكرة التحميل كما يظهر في تذكرة الميزان. هذه عملية قراءة فقط.',
    ui.ButtonSet.OK_CANCEL
  );
  if (response.getSelectedButton() !== ui.Button.OK) return;
  const ticket = response.getResponseText().trim();
  if (!ticket) {
    ui.alert('لم يُدخل رقم تذكرة. لم يتم تغيير أي بيانات.');
    return;
  }
  const result = inspectArrivalTicketByNumber_(ticket);
  ui.alert(result.title, result.message, ui.ButtonSet.OK);
  console.log(JSON.stringify(result.log));
}

/** Returns structured results for a ticket without modifying anything. */
function inspectArrivalTicketByNumber_(ticketInput) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss) throw new Error('افتح السكربت من ملف Google Sheets نفسه (bound script).');
  const loading = ss.getSheetByName(ARRIVAL_A1.loading);
  const offload = ss.getSheetByName(ARRIVAL_A1.offload);
  if (!loading || !offload) throw new Error('لم أجد Loading Register أو Offload Data؛ توقف دون أي تعديل.');
  // Read two copies: displayed ticket/key strings and typed date/weight values.
  const lSize = Math.max(loading.getLastRow(), 1);
  const oSize = Math.max(offload.getLastRow(), 1);
  const lv = loading.getRange(1, 1, lSize, 29).getValues();
  const ld = loading.getRange(1, 1, lSize, 29).getDisplayValues();
  const ov = offload.getRange(1, 1, oSize, 17).getValues();
  const od = offload.getRange(1, 1, oSize, 17).getDisplayValues();
  const norm = x => String(x == null ? '' : x).trim();
  const target = norm(ticketInput);
  if (!target) throw new Error('Ticket is required');
  const loadMatches = [];
  const loadKeyCounts = new Map();
  const offKeyRows = new Map();
  for (let i=1; i<ld.length; i++) {
    const key = norm(ld[i][13]);
    if (key) loadKeyCounts.set(key, (loadKeyCounts.get(key)||0)+1);
    // Keep exact displayed text: do not strip leading zeros from ticket identifiers.
    if (norm(ld[i][0]) === target) loadMatches.push(i);
  }
  for (let i=1; i<od.length; i++) {
    const key = norm(od[i][6]);
    if (!key) continue;
    if (!offKeyRows.has(key)) offKeyRows.set(key, []);
    offKeyRows.get(key).push(i+1);
  }
  const report = [];
  const log = {ticket: target, found:loadMatches.length, candidates:[]};
  if (loadMatches.length === 0) {
    return {title:'لا توجد تذكرة مطابقة',message:
      'لم أجد رقم التذكرة '+target+' في Loading Register!A.\n' +
      'تحقق من الرقم ومن تسجيل تذكرة الميزان أولاً.\nلم تُكتب أي بيانات.',log};
  }
  report.push('التذكرة: '+target+' | عدد سجلات التحميل المطابقة: '+loadMatches.length);
  if (loadMatches.length > 1) report.push('تنبيه: رقم التذكرة غير منفرد؛ لا يجوز اختيار الرحلة تلقائياً. راجع سلسلة المصدر ورقم الشاحنة.');
  const fmt = value => value instanceof Date && !isNaN(value.getTime())
    ? Utilities.formatDate(value, ss.getSpreadsheetTimeZone()||'Asia/Riyadh', 'yyyy-MM-dd HH:mm') : '';
  const visible = loadMatches.slice(0, ARRIVAL_A1.maxMatchesShown);
  for (const i of visible) {
    const key = norm(ld[i][13]);
    const linked = key ? (offKeyRows.get(key)||[]) : [];
    const dupKey = key ? (loadKeyCounts.get(key)||0) : 0;
    const warnings = [];
    if (!key) warnings.push('مفتاح الرحلة فارغ');
    if (dupKey !== 1 && key) warnings.push('مفتاح مكرر في التحميل ('+dupKey+')');
    if (linked.length > 1) warnings.push('تكرار سجلات التفريغ ('+linked.length+')');
    const receiptRow = linked.length===1 ? linked[0] : null;
    const receipt = receiptRow ? ov[receiptRow-1] : null;
    let state = 'لا يوجد سجل تفريغ بعد';
    if (linked.length === 1) {
      state = 'موجود في Offload Data — الصف '+receiptRow;
      if (norm(od[receiptRow-1][11]) === 'Approved' || norm(ld[i][9]) === 'Closed')
        state += ' | معتمد/مغلق: لا تُنشئ سجلاً ثانياً';
    } else if (linked.length > 1) state = 'تعارض: المفتاح موجود في عدة صفوف تفريغ';
    const candidate = {
      loadingRow:i+1, ticket:target, sourceSeries:norm(ld[i][14]),
      tripKey:key, truck:norm(ld[i][5]), carrier:norm(ld[i][4]),
      loadedTons:ld[i][6], loadingStatus:norm(ld[i][20]),
      loadingDate:fmt(lv[i][2]), receiptRows:linked,
      arrival: receipt?fmt(receipt[1]):'', review: receipt?norm(od[receiptRow-1][11]):'',
      warnings
    };
    log.candidates.push(candidate);
    report.push('\nسجل التحميل '+candidate.loadingRow+
      '\nالسلسلة: '+(candidate.sourceSeries||'—')+' | اللوحة: '+(candidate.truck||'—')+
      '\nالناقل: '+(candidate.carrier||'—')+' | الوزن: '+(candidate.loadedTons||'—')+' طن'+
      '\nمفتاح الرحلة (للمراجعة): '+(key||'—')+
      '\nآخر وزن تحميل: '+(candidate.loadingDate||'—')+
      '\nحالة التحميل: '+(candidate.loadingStatus||'—')+
      '\nالربط: '+state+
      (candidate.arrival?'\nوقت الوصول المسجل: '+candidate.arrival:'')+
      (warnings.length?'\nتحذير: '+warnings.join('؛ '):''));
  }
  if (loadMatches.length>visible.length) report.push('\nتوجد نتائج إضافية غير معروضة؛ أوقف الاختيار الآلي.');
  report.push('\nهذه معاينة فقط. لم تتم إضافة رحلة أو تعديل أي خلية.');
  return {title: loadMatches.length===1?'نتيجة البحث عن التذكرة':'تذكرة متعددة المطابقات',message:report.join('\n'),log};
}

/** Read-only structural check before the first lookup. */
function verifyArrivalIntakeReadOnly() {
  const ss=SpreadsheetApp.getActiveSpreadsheet();
  const l=ss.getSheetByName(ARRIVAL_A1.loading), o=ss.getSheetByName(ARRIVAL_A1.offload);
  if(!l || !o) throw new Error('Source worksheets not found.');
  const expectedLoading={1:'Ticket ID',5:'Transporter',6:'Truck No.',14:'Trip Key',15:'Source / Ticket Series'};
  const expectedOffload={1:'Truck No.',2:'Arrival Time',7:'Trip Key',12:'Review Decision'};
  const errors=[];
  Object.keys(expectedLoading).forEach(k=>{if(l.getRange(1,+k).getDisplayValue().trim()!==expectedLoading[k]) errors.push('Loading Register column '+k);});
  Object.keys(expectedOffload).forEach(k=>{if(o.getRange(1,+k).getDisplayValue().trim()!==expectedOffload[k]) errors.push('Offload Data column '+k);});
  if(errors.length) throw new Error('Unrecognized column layout; stopped: '+errors.join(', '));
  SpreadsheetApp.getUi().alert('نجح فحص الأعمدة. هذه الوحدة للبحث فقط، ولا تكتب على أي ورقة.');
  return {ok:true, loadingRows:l.getLastRow(),offloadRows:o.getLastRow()};
}

function testArrivalSpreadsheetAccess() {
  const start = Date.now();
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  const names = [
    'Loading Register',
    'Offload Data'
  ];

  for (const name of names) {
    const sheet = ss.getSheetByName(name);
    if (!sheet) {
      throw new Error('Missing sheet: ' + name);
    }

    console.log(
      name,
      'Last row:', sheet.getLastRow(),
      'Last column:', sheet.getLastColumn()
    );
  }

  console.log('Elapsed ms:', Date.now() - start);
  console.log('Structural access: PASS');
}

function verifyArrivalHeadersFast() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  const checks = [
    {
      name: 'Loading Register',
      columns: [1, 5, 6, 14, 15]
    },
    {
      name: 'Offload Data',
      columns: [1, 2, 7, 12]
    }
  ];

  for (const check of checks) {
    const sheet = ss.getSheetByName(check.name);

    if (!sheet) {
      throw new Error('Missing sheet: ' + check.name);
    }

    const headers = sheet
      .getRange(1, 1, 1, sheet.getLastColumn())
      .getDisplayValues()[0];

    console.log('SHEET: ' + check.name);

    for (const col of check.columns) {
      console.log(
        'Column ' + col + ': ' + headers[col - 1]
      );
    }
  }

  console.log('ARRIVAL HEADERS: PASS');
}

/**
 * SABIL SHIPMENT HAIL — Arrival Intake / Unit 2 (manual offload entry).
 * REPLACE the entire contents of ArrivalIntakeCommit.gs with this file.
 * Keep ArrivalIntake.gs, Code.gs, and CarrierReportViewer.gs unchanged.
 *
 * Only links an existing loading trip to Offload Data!G (Trip Key).
 * Does NOT set arrival time, unloading timestamps, weights, receipt details,
 * review fields, or other operator-entered offload data.
 * The Offload Data!A truck number remains a derived value (existing formula).
 * All prompts and confirmations are in English.
 */
const ARRIVAL_U2 = Object.freeze({
  loading: 'Loading Register',
  offload: 'Offload Data',
  maxReadRows: 100000
});

function registerTruckArrival() {
  const ui = SpreadsheetApp.getUi();
  const ask = ui.prompt(
    'Link loading ticket to offload record',
    'Enter the LOADING ticket number (not the offload weighbridge ticket number).',
    ui.ButtonSet.OK_CANCEL
  );
  if (ask.getSelectedButton() !== ui.Button.OK) return;
  const ticket = String(ask.getResponseText() || '').trim();
  if (!ticket) return ui.alert('A loading ticket number is required. No changes were made.');

  const initial = arrivalU2Check_(ticket);
  if (!initial.ok) return ui.alert('Cannot link trip', initial.reason, ui.ButtonSet.OK);

  const confirmation = ui.alert(
    'Confirm trip link',
    'Loading ticket: ' + ticket + '\n' +
    'Truck: ' + initial.truck + '\n' +
    'Carrier: ' + initial.carrier + '\n' +
    'Trip key: ' + initial.key + '\n\n' +
    'Create a linked Offload Data row?\n\n' +
    'ONLY the trip key will be stored in column G.\n' +
    'Arrival time, unloading times, offload weight, offload ticket, review, and all other offload fields must be entered MANUALLY.\n' +
    'An existing/new formula in column A may display the truck number.',
    ui.ButtonSet.YES_NO
  );
  if (confirmation !== ui.Button.YES) return;

  const lock = LockService.getDocumentLock() || LockService.getScriptLock();
  if (!lock.tryLock(20000)) {
    return ui.alert('Another operation is in progress. No changes were made. Please retry.');
  }
  let completed = null;
  let failure = null;
  try {
    const current = arrivalU2Check_(ticket);
    if (!current.ok) throw new Error('Trip changed during confirmation: ' + current.reason);
    if (current.key !== initial.key || current.truck !== initial.truck || current.loadingRow !== initial.loadingRow) {
      throw new Error('Trip identity changed during confirmation. No changes were made.');
    }
    const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(ARRIVAL_U2.offload);
    const destination = arrivalU2FindFreeRow_(sheet);

    // Do not overwrite manual data. Column A is formula-derived; G is the only
    // operator-link field that will be populated by this function.
    const human = sheet.getRange(destination, 2, 1, 11); // B:L
    const values = human.getDisplayValues()[0];
    const formulas = human.getFormulas()[0];
    if (values.some(v => String(v).trim()) || formulas.some(Boolean)) {
      throw new Error('The destination row is no longer empty. No changes were made.');
    }
    const truckCell = sheet.getRange(destination, 1);
    if (String(truckCell.getDisplayValue()).trim()) {
      throw new Error('The destination truck cell is not blank. No changes were made.');
    }

    // Preserve the existing derived Truck No. behavior. If the row lies beyond
    // the formula template, create the formula in A rather than a manual value.
    if (!truckCell.getFormula()) {
      truckCell.setFormula('=IF(G' + destination + '= "","",IF(COUNTIF(\'Loading Register\'!$N$2:$N,G' + destination + ')<>1,"",INDEX(\'Loading Register\'!$F$2:$F,MATCH(G' + destination + ',\'Loading Register\'!$N$2:$N,0))))');
    }
    // Extend formulas in calculated columns M:Q when a new row lacks them.
    // This function never writes manual entry fields in those columns.
    arrivalU2ExtendComputedFormulas_(sheet, destination);

    // Exactly one operational field is populated: G = loading Trip Key.
    // Column B (arrival time) is deliberately NOT written.
    sheet.getRange(destination, 7).setValue(current.key);
    SpreadsheetApp.flush();
    completed = { row: destination, ticket, truck: current.truck, key: current.key };
    console.log(JSON.stringify({ event: 'OFFLOAD_TRIP_LINKED', ...completed }));
  } catch (err) {
    failure = String(err.message || err);
    console.error('OFFLOAD_LINK_FAILED: ' + failure);
  } finally {
    lock.releaseLock();
  }
  if (failure) return ui.alert('Linking not completed', failure + '\n\nInspect Offload Data before retrying.', ui.ButtonSet.OK);
  ui.alert(
    'Trip linked successfully',
    'Loading ticket: ' + completed.ticket + '\n' +
    'Truck: ' + completed.truck + '\n' +
    'Offload Data row: ' + completed.row + '\n' +
    'Trip key (column G): ' + completed.key + '\n\n' +
    'Enter the ACTUAL arrival time in column B and all other offload information manually.\n' +
    'No timestamps or offload values were entered automatically.',
    ui.ButtonSet.OK
  );
}

/** Read-only eligibility check: loading ticket ONLY in Loading Register!A. */
function arrivalU2Check_(ticket) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss) throw new Error('Open the script bound to the correct Google Sheet.');
  const loading = ss.getSheetByName(ARRIVAL_U2.loading);
  const offload = ss.getSheetByName(ARRIVAL_U2.offload);
  if (!loading || !offload) throw new Error('Missing Loading Register or Offload Data sheet.');
  const fail = reason => ({ ok: false, reason });
  const expected = [
    [loading, 1, 'Ticket ID'], [loading, 6, 'Truck No.'],
    [loading, 14, 'Trip Key'], [offload, 2, 'Arrival Time'],
    [offload, 7, 'Trip Key']
  ];
  for (const [sheet, col, header] of expected) {
    if (sheet.getRange(1, col).getDisplayValue().trim() !== header) {
      return fail('Unexpected header in ' + sheet.getName() + ' at column ' + col + '. No changes were made.');
    }
  }
  const lastLoading = loading.getLastRow();
  const lastOffload = offload.getLastRow();
  if (lastLoading > ARRIVAL_U2.maxReadRows || lastOffload > ARRIVAL_U2.maxReadRows) {
    return fail('Row count exceeds the configured safe search limit.');
  }
  const loads = lastLoading > 1 ? loading.getRange(2, 1, lastLoading - 1, 21).getDisplayValues() : [];
  const offloadKeys = lastOffload > 1 ? offload.getRange(2, 7, lastOffload - 1, 1).getDisplayValues() : [];
  const matches = [];
  const keyCounts = new Map();
  for (let i = 0; i < loads.length; i++) {
    const row = loads[i];
    const key = String(row[13] || '').trim();
    if (key) keyCounts.set(key, (keyCounts.get(key) || 0) + 1);
    if (String(row[0] || '').trim() === ticket) matches.push({ row, sheetRow: i + 2 });
  }
  if (matches.length !== 1) {
    return fail(matches.length === 0
      ? 'Loading ticket not found in Loading Register.'
      : 'Loading ticket is duplicated (' + matches.length + ' records). Manual review required.');
  }
  const hit = matches[0];
  const key = String(hit.row[13] || '').trim();
  const truck = String(hit.row[5] || '').trim();
  const carrier = String(hit.row[4] || '').trim();
  if (!key || !truck || !carrier) return fail('Incomplete loading record: trip key, truck, or carrier is missing.');
  if (keyCounts.get(key) !== 1) return fail('Duplicate trip key in Loading Register.');
  const existing = [];
  for (let i = 0; i < offloadKeys.length; i++) {
    if (String(offloadKeys[i][0] || '').trim() === key) existing.push(i + 2);
  }
  if (existing.length) return fail('Trip key already exists in Offload Data row(s): ' + existing.join(', ') + '. Duplicate linking blocked.');
  const status = String(hit.row[9] || '').trim();
  if (/^(Closed|Hold)$/i.test(status)) return fail('Trip status is ' + status + '. Manual review required.');
  return { ok: true, key, truck, carrier, loadingRow: hit.sheetRow };
}

/** Pick a row with no B:L operator data or formulas. Do not change old rows. */
function arrivalU2FindFreeRow_(sheet) {
  const last = Math.max(sheet.getLastRow(), 2);
  const count = last - 1;
  if (count > 0) {
    const values = sheet.getRange(2, 2, count, 11).getDisplayValues();
    const formulas = sheet.getRange(2, 2, count, 11).getFormulas();
    const trucks = sheet.getRange(2, 1, count, 1).getDisplayValues();
    for (let i = 0; i < count; i++) {
      if (values[i].every(v => !String(v).trim()) &&
          formulas[i].every(f => !f) &&
          !String(trucks[i][0] || '').trim()) return i + 2;
    }
  }
  const destination = last + 1;
  if (destination > sheet.getMaxRows()) {
    sheet.insertRowsAfter(sheet.getMaxRows(), destination - sheet.getMaxRows());
  }
  return destination;
}

/** Fill only genuinely missing formula cells in calculated columns M:Q. */
function arrivalU2ExtendComputedFormulas_(sheet, row) {
  const target = sheet.getRange(row, 13, 1, 5);
  const values = target.getDisplayValues()[0];
  const formulas = target.getFormulas()[0];
  if (values.some(v => String(v).trim() && v !== '#N/A')) return;
  if (formulas.every(Boolean) || row <= 2) return;
  const template = sheet.getRange(row - 1, 13, 1, 5).getFormulasR1C1()[0];
  for (let i = 0; i < 5; i++) {
    if (!formulas[i] && !String(values[i]).trim() && template[i]) {
      sheet.getRange(row, 13 + i).setFormulaR1C1(template[i]);
    }
  }
}

function addTruckOperationsMenu() {
  SpreadsheetApp.getUi()
    .createMenu('Truck Operations')
    .addItem('Link Loading Ticket', 'registerTruckArrival')
    .addToUi();
}

/**
 * SABIL SHIPMENT HAIL — UNIT 2 / Carrier Report Viewer (Google Sheets).
 * Add this as a NEW script file in the SAME spreadsheet-bound Apps Script project.
 * Keep Code.gs (Unit 1) unchanged. Run refreshCarrierReportViewer once.
 * Uses ONLY the already-built Carrier Daily Report A:O; never edits it or sources.
 * Period movement is SUMMED, while EOD balance is a SNAPSHOT at the end date.
 * Tonnes and alert > 1 tonne are inherited from Unit 1.
 */
const CARRIER_VIEWER_V2 = Object.freeze({ledger:'Carrier Daily Report', viewer:'Carrier Report Viewer', firstDataRow:6});

function refreshCarrierReportViewer() {
  const ss=SpreadsheetApp.getActiveSpreadsheet();
  const ledger=ss.getSheetByName(CARRIER_VIEWER_V2.ledger);
  if(!ledger)throw new Error('Missing Carrier Daily Report. Run refreshCarrierDailyReport first.');
  const tz=ss.getSpreadsheetTimeZone()||'Asia/Riyadh';
  const raw=ledger.getLastRow()>=6 ? ledger.getRange(6,1,ledger.getLastRow()-5,15).getValues() : [];
  const dayOf=v=> {
    if(v instanceof Date && !isNaN(v.getTime()))return Utilities.formatDate(v,tz,'yyyy-MM-dd');
    if(typeof v==='string' && /^\d{4}-\d{2}-\d{2}$/.test(v.trim()))return v.trim();
    return '';
  };
  const num=x=>typeof x==='number'&&isFinite(x)?x:0;
  const records=raw.map(r=>({day:dayOf(r[0]), carrier:String(r[1]||'').trim(),r})).filter(x=>x.day&&x.carrier);
  records.sort((a,b)=>a.day.localeCompare(b.day)||a.carrier.localeCompare(b.carrier));
  const names=[...new Set(records.map(x=>x.carrier))].sort((a,b)=>a.localeCompare(b));
  const earliest=records.length?records[0].day:'';
  const latest=records.length?records[records.length-1].day:'';
  const sheet=ss.getSheetByName(CARRIER_VIEWER_V2.viewer)||ss.insertSheet(CARRIER_VIEWER_V2.viewer);
  // Preserve user selection and never clear the source ledger or other sheets.
  const priorFrom=dayOf(sheet.getRange('B3').getValue());
  const priorTo=dayOf(sheet.getRange('B4').getValue());
  const priorCarrier=String(sheet.getRange('B5').getValue()||'').trim();
  const from=priorFrom||(earliest||Utilities.formatDate(new Date(),tz,'yyyy-MM-dd'));
  const to=priorTo||(latest||from);
  const carrier=priorCarrier||'All';
  if(from>to)throw new Error('From date cannot be after To date (B3/B4).');
  if(carrier!=='All'&&!names.includes(carrier))throw new Error('Carrier in B5 is not in the daily ledger: '+carrier);
  const target=carrier==='All'?names:[carrier];
  const result=calculateCarrierViewerV2(records,target,from,to,num);
  // Output-only reset: user inputs (B3:B5) are deliberately preserved.
  const oldFilter=sheet.getFilter();if(oldFilter)oldFilter.remove();
  sheet.getRange(1,1,Math.min(sheet.getMaxRows(),3),Math.min(sheet.getMaxColumns(),12)).breakApart();
  sheet.getRange(1,1,sheet.getMaxRows(),12).clearContent();
  sheet.getRange(1,1,Math.min(sheet.getMaxRows(),Math.max(40,records.length+30)),12).clearFormat();
  sheet.getRange('A1:H1').merge().setValue('CARRIER REPORT VIEWER | استعراض التقارير اليومية والتراكمية');
  sheet.getRange('A3:A5').setValues([['From / من تاريخ'],['To / إلى تاريخ'],['Carrier / الناقل']]);
  sheet.getRange('B3:B5').setValues([[from],[to],[carrier]]);
  sheet.getRange('A7:H7').setValues([['Loaded trips','Loaded (tonnes)','Arrived trips','Offloaded trips','Received (tonnes)','Weight variance >1t','Unverified arrivals','EOD open trips']]);
  sheet.getRange('A8:H8').setValues([[result.totals.loaded,result.totals.loadTons,result.totals.arrived,result.totals.offloaded,result.totals.receivedTons,result.totals.variance,result.totals.unverified,result.totals.open]]);
  sheet.getRange('A10:H10').setValues([['Carrier / الناقل','Loaded trips','Load tonnes','Arrived trips','Offloaded trips','Received tonnes','Not arrived EOD','Await offload EOD']]);
  // A11:H... is the main carrier comparison. Flags beneath it show control totals.
  const table=result.details.map(d=>[d.carrier,d.loaded,d.loadTons,d.arrived,d.offloaded,d.receivedTons,d.notArrived,d.awaitOffload]);
  if(table.length)sheet.getRange(11,1,table.length,8).setValues(table);
  const flagsStart=12+table.length;
  sheet.getRange(flagsStart,1,1,8).setValues([['Carrier / الناقل','Variance >1t','Unverified offloads','Arrival deficit EOD','Offload deficit EOD','','','']]);
  if(result.details.length)sheet.getRange(flagsStart+1,1,result.details.length,5).setValues(result.details.map(d=>[d.carrier,d.variance,d.unverified,d.arrivalDeficit,d.offloadDeficit]));
  const warning=[];
  if(!records.length)warning.push('No daily ledger data. Refresh Unit 1 first.');
  if(latest && to>latest)warning.push('End date exceeds last ledger date '+latest+'; refresh Unit 1 before relying on EOD balance.');
  if(earliest && from<earliest)warning.push('Requested range starts before available ledger history '+earliest+'.');
  if(!result.anyMovement)warning.push('No loading/arrival/offload movements during selected dates; EOD balances may still be nonzero.');
  sheet.getRange('D3').setValue('Ledger coverage');sheet.getRange('E3').setValue(earliest&&latest?earliest+' to '+latest:'No records');
  sheet.getRange('D4').setValue('Report method');sheet.getRange('E4').setValue('Movements summed; open balances as of end date');
  sheet.getRange('D5').setValue('Alert threshold');sheet.getRange('E5').setValue('More than 1 tonne');
  sheet.getRange('A6:H6').merge().setValue(warning.length?warning.join(' | '):'Totals are for the chosen period. Open balances / deficits are end-of-period snapshots.');
  const validation=SpreadsheetApp.newDataValidation().requireValueInList(['All',...names],true).setAllowInvalid(false).build();
  sheet.getRange('B5').setDataValidation(validation);
  // Date inputs support both Sheets date cells and ISO yyyy-mm-dd text; validated by dayOf() above.
  // Do not apply a text-pattern validator: it is not available in Apps Script DataValidationBuilder.
  sheet.getRange('B3:B4').clearDataValidations();
  sheet.setFrozenRows(10);
  sheet.getRange('A1:H1').setBackground('#123047').setFontColor('white').setFontWeight('bold').setFontSize(13);
  sheet.getRange('A7:H7').setBackground('#087e8b').setFontColor('white').setFontWeight('bold').setWrap(true);
  sheet.getRange('A10:H10').setBackground('#123047').setFontColor('white').setFontWeight('bold').setWrap(true);
  sheet.getRange(flagsStart,1,1,8).setBackground('#087e8b').setFontColor('white').setFontWeight('bold').setWrap(true);
  sheet.getRange('A3:A5').setBackground('#e5f0f3').setFontWeight('bold');sheet.getRange('B3:B5').setBackground('#fff2cc');
  sheet.getRange('A8:H8').setFontWeight('bold').setBackground('#e5f0f3');
  sheet.getRange('B8').setNumberFormat('#,##0.000');sheet.getRange('E8').setNumberFormat('#,##0.000');
  sheet.getRange('C8').setNumberFormat('0');sheet.getRange('F8:H8').setNumberFormat('0');
  if(table.length){sheet.getRange(11,3,table.length,1).setNumberFormat('#,##0.000');sheet.getRange(11,6,table.length,1).setNumberFormat('#,##0.000');}
  sheet.setColumnWidth(1,192);sheet.setColumnWidth(2,168);
  for(let j=3;j<=8;j++)sheet.setColumnWidth(j,160);
  sheet.setRowHeight(1,34);sheet.setRowHeight(7,46);sheet.setRowHeight(10,42);sheet.setRowHeight(flagsStart,42);
  sheet.getRange('A6:H6').setWrap(true).setFontColor(warning.length?'#a3381a':'#22543d');
  sheet.setRowHeight(6,warning.length?64:36);
  return {from,to,carrier,carriersReported:result.details.length,ledgerDates:{earliest,latest},warnings:warning};
}

/** Pure summarizer: safe to test outside Apps Script. */
function calculateCarrierViewerV2(records,names,from,to,num) {
  const details=[];
  let anyMovement=false;
  const totals={loaded:0,loadTons:0,arrived:0,offloaded:0,receivedTons:0,variance:0,unverified:0,notArrived:0,awaitOffload:0,arrivalDeficit:0,offloadDeficit:0,open:0};
  for(const carrier of names){
    const all=records.filter(x=>x.carrier===carrier&&x.day<=to).sort((a,b)=>a.day.localeCompare(b.day));
    const inPeriod=all.filter(x=>x.day>=from);
    const add=index=>inPeriod.reduce((s,x)=>s+num(x.r[index]),0);
    const last=all.length?all[all.length-1].r:null;
    const d={carrier,loaded:add(2),loadTons:add(3),arrived:add(4),offloaded:add(5),receivedTons:add(6),variance:add(9),unverified:add(12),
      notArrived:last?num(last[7]):0,awaitOffload:last?num(last[8]):0,arrivalDeficit:last?num(last[13]):0,offloadDeficit:last?num(last[14]):0};
    anyMovement=anyMovement||d.loaded>0||d.arrived>0||d.offloaded>0;
    for(const key of ['loaded','loadTons','arrived','offloaded','receivedTons','variance','unverified','notArrived','awaitOffload','arrivalDeficit','offloadDeficit'])totals[key]+=d[key];
    details.push(d);
  }
  totals.open=totals.notArrived+totals.awaitOffload;
  // The daily ledger intentionally clips negative balances and records deficits separately.
  // These are reported separately, not netted out.
  return {details,totals,anyMovement};
}

