/** True only for an already completed panel wholly within A:D. */
function inlineAuditIsComplete_(sheet, top) {
  const height = SABIL_INLINE_AUDIT.height;
  if (top + height - 1 > sheet.getMaxRows()) return false;
  const range = sheet.getRange(top, 1, height, 4);
  for (const merged of range.getMergedRanges()) {
    if (merged.getRow() < top || merged.getLastRow() > top + height - 1 ||
        merged.getColumn() < 1 || merged.getLastColumn() > 4) return false;
  }
  return sheet.getRange(top, 1).getDisplayValue() === SABIL_INLINE_AUDIT.marker &&
    sheet.getRange(top + 2, 1).getDisplayValue() === 'Metric' &&
    sheet.getRange(top + 3, 1).getDisplayValue() === 'Records reviewed' &&
    sheet.getRange(top + 7, 1).getDisplayValue() === 'Approved with findings' &&
    sheet.getRange(top + 11, 1).getDisplayValue() === 'Source';
}

/**
 * SABIL SHIPMENT HAIL — Dashboard Logic Reconciliation (one-step).
 * Run reconcileSabilDashboardLogic once in the bound Google Sheets project.
 * Changes ONLY approved dashboard formula ranges and one descriptive label.
 * Never writes to shipment records, audit panels, manual approvals, or triggers.
 * Source formulas from SABIL_SHIPMENT_HAIL(3).xlsx are used as a safety baseline.
 */
const SABIL_DASHBOARD_RECONCILE = Object.freeze({
  sheet: 'Dashboard',
  // Only the original operational scorecard formula locations.
  formulaCells: [
    'B4','D4','B5','D5','B6','D6','B7','D7','B8','D8',
    'B9','D9','B10','D10','B11','B15','D15','B16','D16'
  ],
  // Template capacity is an intentional bounded measure; do not change D11.
  capacityCell: 'D11',
  originalVarianceLabel: 'Weight variance (paired tons)',
  updatedVarianceLabel: 'Net Weight Variance (tonnes)'
});

function reconcileSabilDashboardLogic() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sh = ss.getSheetByName(SABIL_DASHBOARD_RECONCILE.sheet);
  if (!sh) throw new Error('Dashboard not found. No changes made.');

  // Preflight all proposed changes before any writing.
  const modifications = [];
  const skipped = [];
  const unchanged = [];
  const fixedEnding = /(\$?[A-Z]{1,3}\$?2:\$?[A-Z]{1,3})\$?(?:102|1000)(?!\d)/g;
  const boundedReference = /\$?[A-Z]{1,3}\$?2:\$?[A-Z]{1,3}\$?(?:102|1000)(?!\d)/;

  for (const addr of SABIL_DASHBOARD_RECONCILE.formulaCells) {
    const oldFormula = sh.getRange(addr).getFormula();
    if (!oldFormula) {
      skipped.push(addr + ': no formula; protected from overwrite');
      continue;
    }
    // Only source-backed aggregate formulas, not formulas of a new design.
    if (!/^(=)?(?:COUNTIF|COUNTIFS|SUM|SUMIFS|IF)\(/i.test(oldFormula)) {
      skipped.push(addr + ': unexpected formula; unchanged');
      continue;
    }
    // The range expansion may only affect Loading Register or Offload Data,
    // not arbitrary external sheets, dates, constants, or capacities.
    if (!oldFormula.includes("'Loading Register'!") &&
        !oldFormula.includes("'Offload Data'!")) {
      skipped.push(addr + ': unknown source; unchanged');
      continue;
    }
    const updated = oldFormula.replace(fixedEnding, '$1');
    if (updated === oldFormula) {
      unchanged.push(addr);
      continue;
    }
    // Reject any unrecognized fixed 102/1000 references remaining.
    if (boundedReference.test(updated)) {
      skipped.push(addr + ': fixed reference remained; unchanged');
      continue;
    }
    // Range expressions only; do not change any criteria or counting definition.
    modifications.push({addr, oldFormula, updated});
  }

  // Validate all destination ranges before writing; do not alter merged content.
  for (const item of modifications) {
    const range = sh.getRange(item.addr);
    if (range.isPartOfMerge()) {
      throw new Error('Merged dashboard formula cell ' + item.addr +
        '. No changes made.');
    }
  }

  const labelCell = sh.getRange('A11');
  const oldLabel = labelCell.getDisplayValue().trim();
  const changeLabel = oldLabel === SABIL_DASHBOARD_RECONCILE.originalVarianceLabel;
  if (!changeLabel && oldLabel !== SABIL_DASHBOARD_RECONCILE.updatedVarianceLabel) {
    skipped.push('A11: label differs from source; unchanged');
  }

  // Snapshot exact originals, so a write failure can restore touched cells.
  const applied = [];
  try {
    for (const item of modifications) {
      sh.getRange(item.addr).setFormula(item.updated);
      applied.push(item);
    }
    if (changeLabel) {
      labelCell.setValue(SABIL_DASHBOARD_RECONCILE.updatedVarianceLabel);
    }
    SpreadsheetApp.flush();
  } catch (err) {
    for (let i = applied.length - 1; i >= 0; i--) {
      try { sh.getRange(applied[i].addr).setFormula(applied[i].oldFormula); }
      catch (rollbackError) { console.error('Rollback failed at ' + applied[i].addr + ': ' + rollbackError); }
    }
    if (changeLabel) {
      try { labelCell.setValue(oldLabel); } catch (_) {}
    }
    throw new Error('Reconciliation failed; attempted rollback of changed cells: ' + err);
  }

  const summary = {
    event: 'SABIL_DASHBOARD_LOGIC_RECONCILED',
    expandedFormulaCells: modifications.map(x => x.addr),
    formulasAlreadyOpenOrUnchanged: unchanged,
    untouchedAndFlagged: skipped,
    capacityFormulaD11Preserved: true,
    varianceLabelUpdated: changeLabel,
    shipmentSourcesChanged: false,
    auditPanelsChanged: false,
    triggersChanged: false
  };
  console.log(JSON.stringify(summary));
  ss.toast('Dashboard reconciliation complete: ' + modifications.length +
    ' formulas expanded; source records unchanged.', 'SABIL Dashboard', 8);
  return summary;
}

/**
 * SABIL — Dashboard audit summary, one-step installation.
 * Paste as a NEW .gs script file in the existing, spreadsheet-bound Apps Script project.
 * Run installOffloadDashboardSummary() ONCE.
 * Writes ONLY Dashboard!T3:W14 (dedicated panel). Never alters loading/offload,
 * operational audit, human approvals, or existing dashboard cells outside this panel.
 * Reads the existing Offload Operations Audit report. Existing audit semantics remain intact.
 * The central simple onEdit dispatcher refreshes this after the audit succeeds.
 */
const OFFLOAD_DASH_PANEL = Object.freeze({
  dashboard: 'Dashboard', audit: 'Offload Operations Audit',
  handler: 'refreshOffloadDashboardSummary',
  firstRow: 3, firstCol: 20, rows: 12, cols: 4,
  marker: 'SABIL_OFFLOAD_AUDIT_PANEL_V1', tolerance: 1
});

/** Noninteractive compatibility initializer. Blueprint already contains the clean panel. */
function installOffloadDashboardSummary() { return refreshOffloadDashboardSummary(); }

function refreshOffloadDashboardSummary() {
  const cfg = OFFLOAD_DASH_PANEL;
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const audit = ss.getSheetByName(cfg.audit);
  const dash = ss.getSheetByName(cfg.dashboard);
  if (!audit || !dash) throw new Error('Required sheet missing: Dashboard or Offload Operations Audit. Nothing written.');

  // Read complete report BEFORE writing; don't infer a clean state from a missing/partial audit.
  const heads = audit.getRange('A5:M5').getDisplayValues()[0];
  if (heads[0] !== 'Offload row' || heads[5] !== 'Operational assessment' ||
      heads[6] !== 'Findings' || heads[11] !== 'Difference tonnes' ||
      heads[12] !== 'Review Decision') {
    throw new Error('Unexpected audit columns; the dashboard was not changed.');
  }
  const reviewed = audit.getRange('E2').getValue();
  const attention = audit.getRange('H2').getValue();
  const auditUpdated = audit.getRange('B2').getValue();
  if (typeof reviewed !== 'number' || typeof attention !== 'number' ||
      !(auditUpdated instanceof Date) || !isFinite(auditUpdated.getTime())) {
    throw new Error('Audit summary is missing or invalid; the dashboard was not changed.');
  }
  const count = Math.max(0, audit.getLastRow() - 5);
  const entries = count ? audit.getRange(6, 1, count, 13).getValues().filter(r => typeof r[0] === 'number') : [];
  if (entries.length !== reviewed) throw new Error('Audit row count mismatch; update the audit sheet first. No dashboard change.');
  const validApproved = entries.filter(r => r[5] === 'Approved').length;
  const approvalDecisions = entries.filter(r => r[12] === 'Approved').length;
  const held = entries.filter(r => r[12] === 'Hold').length;
  const pendingArrival = entries.filter(r => r[5] === 'Linked / awaiting arrival').length;
  const largeVariance = entries.filter(r => typeof r[11] === 'number' && Number.isFinite(r[11]) && Math.abs(r[11]) > cfg.tolerance + 1e-9).length;
  const completedWithoutArrival = entries.filter(r => String(r[6]).includes('Completed offload without verified arrival')).length;
  const approvedWithExceptions = entries.filter(r => r[12] === 'Approved' && r[6] !== 'OK').length;
  const countedExceptions = entries.filter(r => r[6] !== 'OK').length;
  if (countedExceptions !== attention) throw new Error('Audit exceptions mismatch; dashboard remains unchanged.');

  // Refuse to overwrite ANY existing Dashboard data or formulas except our marked panel.
  const panel = dash.getRange(cfg.firstRow, cfg.firstCol, cfg.rows, cfg.cols);
  const marker = dash.getRange('T3').getValue();
  if (marker !== cfg.marker) {
    const vals = panel.getValues(), formulas = panel.getFormulas();
    if (vals.some((row, i) => row.some((v, j) => v !== '' || formulas[i][j] !== ''))) {
      throw new Error('Dashboard!T3:W14 contains existing content. Nothing was overwritten.');
    }
  }
  if (panel.isPartOfMerge()) {
    // Only existing installations own merges here; unknown merges must not be broken.
    if (marker !== cfg.marker) throw new Error('Dashboard panel overlaps existing merged cells. No changes made.');
    panel.breakApart();
  }

  const cells = Array.from({length: cfg.rows}, () => ['', '', '', '']);
  cells[0] = [cfg.marker, '', '', ''];
  cells[1] = ['OFFLOAD CONTROL SUMMARY', '', '', ''];
  cells[2] = ['Records reviewed', reviewed, 'Need attention', attention];
  cells[3] = ['Approved (valid)', validApproved, 'Approval decisions', approvalDecisions];
  cells[4] = ['On hold', held, 'Awaiting arrival', pendingArrival];
  cells[5] = ['Variance > 1 tonne', largeVariance, 'Missing verified arrival', completedWithoutArrival];
  cells[6] = ['Approved with findings', approvedWithExceptions, 'Allowed variance (tonnes)', cfg.tolerance];
  cells[8] = ['Audit last refreshed', auditUpdated, '', ''];
  cells[9] = ['Panel last refreshed', new Date(), '', ''];
  cells[10] = ['Source', 'Offload Operations Audit', '', ''];
  cells[11] = ['Advisory only — source sheets and review decisions remain authoritative.', '', '', ''];
  panel.clearContent();
  panel.setValues(cells);
  dash.getRange('T4:W4').merge().setBackground('#123047').setFontColor('#ffffff').setFontWeight('bold');
  dash.getRange('T3').setFontColor('#888888').setFontSize(8);
  dash.getRange('T5:W9').setBackground('#edf5f7');
  dash.getRange('T5:T9').setFontWeight('bold');
  dash.getRange('V5:V9').setFontWeight('bold');
  dash.getRange('U5:U9').setNumberFormat('0');
  dash.getRange('W5:W9').setNumberFormat('0');
  dash.getRange('U11').setNumberFormat('yyyy-mm-dd hh:mm');
  dash.getRange('U12').setNumberFormat('yyyy-mm-dd hh:mm');
  dash.getRange('T14:W14').merge().setWrap(true).setFontSize(9).setFontColor('#555555');
  dash.setColumnWidth(20, 225); dash.setColumnWidth(21, 170);
  dash.setColumnWidth(22, 230); dash.setColumnWidth(23, 110);
  dash.setRowHeight(4, 30); dash.setRowHeight(14, 38);
  return {reviewed, attention, validApproved, approvalDecisions, held, largeVariance, approvedWithExceptions};
}

/**
 * SABIL SHIPMENT HAIL — One-step Offload Operational Audit.
 * Add this as a NEW Apps Script file and run applyOffloadOperationalAudit once.
 * Existing sheets and user-entered fields are NEVER written to or cleared.
 * Creates/refreshes only "Offload Operations Audit" and uses the central edit dispatcher.
 * All interface/report labels are in English. Weight tolerance: strictly > 1 tonne.
 */
const OFFLOAD_AUDIT_V1 = Object.freeze({
  loading: 'Loading Register', offload: 'Offload Data',
  report: 'Offload Operations Audit', tolerance: 1,
  trigger: 'offloadAuditOnEdit'
});

/** Noninteractive compatibility initializer; no trigger registration. */
function applyOffloadOperationalAudit() { return offloadAuditRefresh_(); }

function offloadAuditOnEdit(e) {
  if (!e || !e.range) return;
  const name = e.range.getSheet().getName();
  if (name !== OFFLOAD_AUDIT_V1.loading && name !== OFFLOAD_AUDIT_V1.offload) return;
  const lock = LockService.getDocumentLock() || LockService.getScriptLock();
  if (!lock.tryLock(1000)) return;
  try { offloadAuditRefresh_(); }
  catch (err) { console.error('OFFLOAD_AUDIT_REFRESH_FAILED: ' + (err.stack || err)); }
  finally { lock.releaseLock(); }
}

function offloadAuditRefresh_() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const loadSheet = ss.getSheetByName(OFFLOAD_AUDIT_V1.loading);
  const offSheet = ss.getSheetByName(OFFLOAD_AUDIT_V1.offload);
  if (!loadSheet || !offSheet) throw new Error('Missing Loading Register or Offload Data. No source changes made.');

  const loadRows = Math.max(0, loadSheet.getLastRow() - 1);
  const offRows = Math.max(0, offSheet.getLastRow() - 1);
  const loads = loadRows ? loadSheet.getRange(2,1,loadRows,29).getValues() : [];
  const receipts = offRows ? offSheet.getRange(2,1,offRows,17).getValues() : [];
  const clean = v => String(v === null || v === undefined ? '' : v).trim();
  const validDate = v => v instanceof Date && !isNaN(v.getTime());
  const has = v => v !== '' && v !== null && v !== undefined;
  const numeric = v => typeof v === 'number' && isFinite(v) && v > 0;

  const loadingByKey = new Map(), offloadKeyCounts = new Map();
  for (let i=0;i<loads.length;i++) {
    const k = clean(loads[i][13]);
    if (!k) continue;
    if (!loadingByKey.has(k)) loadingByKey.set(k, []);
    loadingByKey.get(k).push({row:i+2, r:loads[i]});
  }
  for (const r of receipts) {
    const k=clean(r[6]);
    if (k) offloadKeyCounts.set(k,(offloadKeyCounts.get(k)||0)+1);
  }

  const counts = {linked:0, awaitingArrival:0, waitingUnloading:0, unloading:0,
    awaitingReview:0, approved:0, held:0, exceptions:0};
  const findings = [];
  let reviewed=0;
  for (let i=0;i<receipts.length;i++) {
    const r=receipts[i], rowNum=i+2, key=clean(r[6]);
    // Ignore truly unused template rows even when calculated formula columns contain values.
    if (!key && !r.slice(1,12).some(has)) continue;
    reviewed++;
    const problems=[];
    let ticket='', truck=clean(r[0]), carrier='', loaded=null;
    const loadMatches=loadingByKey.get(key)||[];
    if (!key) problems.push('Missing trip key');
    else if (loadMatches.length===0) problems.push('Trip key not in Loading Register');
    else if (loadMatches.length!==1) problems.push('Duplicate loading trip key');
    if (key && offloadKeyCounts.get(key)>1) problems.push('Duplicate Offload Data trip key');
    const load=loadMatches.length===1 ? loadMatches[0].r : null;
    if (load) {
      ticket=clean(load[0]); truck=clean(load[5]); carrier=clean(load[4]);
      if (clean(load[20])!=='Ready') problems.push('Loading record not Ready');
      const sourceNet=load[19], sourceUnit=clean(load[16]).toLowerCase();
      const parsed=typeof sourceNet==='number' ? sourceNet : null;
      if (parsed!==null && isFinite(parsed) && parsed>0) {
        if (sourceUnit==='kg'||sourceUnit==='kilogram'||sourceUnit==='kilograms') loaded=parsed/1000;
        else if (['ton','tons','tonne','tonnes','t'].includes(sourceUnit)) loaded=parsed;
        else problems.push('Unknown loading weight unit');
      } else problems.push('Invalid loading net weight');
    }
    const arrival=r[1], completion=r[2], received=r[3], destination=clean(r[4]),
      remarks=clean(r[5]), start=r[7], offloadTicket=clean(r[8]), reviewer=clean(r[9]),
      reviewedAt=r[10], decision=clean(r[11]);
    const arrivalOk=validDate(arrival), startOk=validDate(start), finishOk=validDate(completion);
    if (has(arrival) && !arrivalOk) problems.push('Invalid arrival timestamp');
    if (has(start) && !startOk) problems.push('Invalid unloading start timestamp');
    if (has(completion) && !finishOk) problems.push('Invalid unloading complete timestamp');
    if (load && arrivalOk && validDate(load[2]) && arrival < load[2]) problems.push('Arrival before loading complete');
    if (startOk && !arrivalOk) problems.push('Unloading start without valid arrival');
    if (startOk && arrivalOk && start < arrival) problems.push('Unloading start before arrival');
    if (finishOk && !startOk) problems.push('Unloading completed without valid start');
    if (finishOk && startOk && completion < start) problems.push('Unloading completed before start');
    if (finishOk && !arrivalOk) problems.push('Completed offload without verified arrival');
    if (has(received) && !numeric(received)) problems.push('Invalid offload weight');
    if (finishOk && !numeric(received)) problems.push('Missing valid offload weight');
    if (finishOk && !destination) problems.push('Missing destination');
    if (finishOk && !offloadTicket) problems.push('Missing offload ticket / receipt');
    const difference = loaded!==null && numeric(received) ? Math.round((loaded-received)*1000000)/1000000 : null;
    if (difference!==null && Math.abs(difference)>OFFLOAD_AUDIT_V1.tolerance+1e-9 && !remarks)
      problems.push('Weight variance > 1 tonne requires remarks');
    if (decision && !['Approved','Hold'].includes(decision)) problems.push('Invalid review decision');
    if (decision==='Approved' && (!finishOk||!reviewer||!validDate(reviewedAt)|| (finishOk && validDate(reviewedAt) && reviewedAt<completion)))
      problems.push('Approval without complete, valid review details');
    if (decision==='Approved' && problems.length) problems.push('Approved despite unresolved exceptions');

    let state='Linked / awaiting arrival';
    if (!arrivalOk) counts.awaitingArrival++;
    else if (!startOk) {state='Arrived / awaiting unloading';counts.waitingUnloading++;}
    else if (!finishOk) {state='Unloading';counts.unloading++;}
    else if (decision==='Approved') {state='Approved';counts.approved++;}
    else if (decision==='Hold') {state='On hold';counts.held++;}
    else {state='Awaiting review';counts.awaitingReview++;}
    if (problems.length) {state='Attention required';counts.exceptions++;}
    counts.linked++;
    // Keep both correct states and exceptions on separate audit, without mutating human decisions.
    findings.push([rowNum, ticket, key, truck, carrier, state, problems.length ? problems.join('; ') : 'OK',
      arrivalOk?arrival:'',startOk?start:'',finishOk?completion:'',numeric(received)?received:'',
      difference===null?'':difference, decision]);
  }

  // Complete analysis before touching the reporting sheet; source sheets stay read-only.
  const out=ss.getSheetByName(OFFLOAD_AUDIT_V1.report)||ss.insertSheet(OFFLOAD_AUDIT_V1.report);
  const oldFilter=out.getFilter(); if(oldFilter)oldFilter.remove();
  out.getRange(1,1,1,Math.min(out.getMaxColumns(),13)).breakApart();
  out.clear();
  out.getRange('A1:M1').merge().setValue('OFFLOAD OPERATIONS AUDIT | Read-only source controls');
  out.getRange('A2').setValue('Updated');out.getRange('B2').setValue(new Date()).setNumberFormat('yyyy-mm-dd hh:mm');
  out.getRange('D2').setValue('Reviewed records');out.getRange('E2').setValue(reviewed);
  out.getRange('G2').setValue('Attention required');out.getRange('H2').setValue(counts.exceptions);
  out.getRange('J2').setValue('Allowed variance (tonnes)');out.getRange('K2').setValue(OFFLOAD_AUDIT_V1.tolerance);
  out.getRange('A3:M3').merge().setValue('Manual inputs are never changed. This report is advisory; existing Receipt Data Status, approvals and reporting formulas remain authoritative until separately reconciled.');
  const heads=['Offload row','Loading ticket','Trip Key','Truck No.','Carrier','Operational assessment','Findings','Arrival Time','Unloading Start','Unloading Complete','Received tonnes','Difference tonnes','Review Decision'];
  out.getRange(5,1,1,13).setValues([heads]);
  if(findings.length) {
    out.getRange(6,1,findings.length,13).setValues(findings);
    out.getRange(6,8,findings.length,3).setNumberFormat('yyyy-mm-dd hh:mm');
    out.getRange(6,11,findings.length,2).setNumberFormat('#,##0.000');
    out.getRange(5,1,findings.length+1,13).createFilter();
  }
  out.setFrozenRows(5);
  out.getRange('A1:M1').setBackground('#123047').setFontColor('#ffffff').setFontWeight('bold');
  out.getRange('A5:M5').setBackground('#087e8b').setFontColor('#ffffff').setFontWeight('bold').setWrap(true);
  out.setRowHeight(1,32);out.setRowHeight(5,40);
  out.setColumnWidth(1,110);out.setColumnWidth(2,115);out.setColumnWidth(3,165);
  out.setColumnWidth(4,135);out.setColumnWidth(5,140);out.setColumnWidth(6,180);
  out.setColumnWidth(7,390);
  for(let c=8;c<=10;c++)out.setColumnWidth(c,165);
  for(let c=11;c<=13;c++)out.setColumnWidth(c,140);
  return {reviewed,exceptions:counts.exceptions,linked:counts.linked,approved:counts.approved,held:counts.held};
}

/**
 * SABIL — Review Workflow
 * J: Reviewer
 * K: Approval timestamp
 * L: Hold / Approved
 * All offload data remains manual.
 */

const SABIL_REVIEW_FLOW = {
  sheet: 'Offload Data',
  reviewers: [
    'Ali Hadi',
    'Abbass Abdelhalim'
  ],
  allowedVarianceTons: 1
};

function installSabilReviewFlow() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SABIL_REVIEW_FLOW.sheet);
  if (!sheet) throw new Error('Offload Data not found.');

  const rule = SpreadsheetApp.newDataValidation()
    .requireValueInList(SABIL_REVIEW_FLOW.reviewers, true)
    .setAllowInvalid(false)
    .build();

  sheet.getRange(2, 10, sheet.getMaxRows() - 1, 1)
    .setDataValidation(rule);

  console.log('SABIL_REVIEW_WORKFLOW_INSTALLED');
}

function sabilReviewWorkflowEdited(e) {
  if (!e || !e.range) return;

  const sheet = e.range.getSheet();
  if (sheet.getName() !== SABIL_REVIEW_FLOW.sheet) return;

  const cell = e.range;
  if (cell.getNumRows() !== 1 || cell.getNumColumns() !== 1) return;

  const row = cell.getRow();
  const col = cell.getColumn();
  if (row < 2) return;

  const tripKey = String(sheet.getRange(row, 7).getDisplayValue()).trim();
  if (!tripKey) return;

  const decisionCell = sheet.getRange(row, 12);
  const reviewerCell = sheet.getRange(row, 10);
  const timeCell = sheet.getRange(row, 11);

  const decision = String(decisionCell.getValue()).trim();

  // First manual input puts a new, unreviewed trip on Hold.
  const inputColumns = [2, 3, 4, 5, 6, 8, 9];

  if (inputColumns.includes(col)) {
    if (!decision && !timeCell.getValue()) {
      decisionCell.setValue('Hold');
    }
    return;
  }

  // Approval happens through reviewer selection in J only.
  if (col !== 10) return;
  if (decision === 'Approved') return;

  const reviewer = String(reviewerCell.getValue()).trim();
  if (!reviewer) return;

  if (!SABIL_REVIEW_FLOW.reviewers.includes(reviewer)) {
    reviewerCell.clearContent();
    return;
  }

  const arrival = sheet.getRange(row, 2).getValue();
  const finish = sheet.getRange(row, 3).getValue();
  const received = sheet.getRange(row, 4).getValue();
  const destination = sheet.getRange(row, 5).getValue();
  const remarks = sheet.getRange(row, 6).getValue();
  const unloadingStart = sheet.getRange(row, 8).getValue();
  const receipt = sheet.getRange(row, 9).getValue();

  // Loading information already linked through the trip key.
  const loadingComplete = sheet.getRange(row, 17).getValue();
  const loadingTime = sheet.getRange(row, 15).getValue();
  const loadedTons = sheet.getRange(row, 16).getValue();

  const validDate = v =>
    v instanceof Date && !isNaN(v.getTime());

  const validNumber = v =>
    v !== '' && v !== null &&
    isFinite(Number(v)) && Number(v) > 0;

  const errors = [];

  if (String(loadingComplete).trim() !== 'Ready') {
    errors.push('Loading information is not ready');
  }

  if (!validDate(arrival) ||
      !validDate(unloadingStart) ||
      !validDate(finish)) {
    errors.push('Missing or invalid timestamps');
  } else {
    if (unloadingStart < arrival || finish < unloadingStart) {
      errors.push('Invalid unloading chronology');
    }

    if (validDate(loadingTime) && arrival < loadingTime) {
      errors.push('Arrival precedes loading');
    }
  }

  if (!validNumber(received)) {
    errors.push('Missing or invalid offload weight');
  }

  if (!String(destination).trim() || !String(receipt).trim()) {
    errors.push('Destination or receipt is missing');
  }

  if (!validNumber(loadedTons)) {
    errors.push('Missing or invalid loading weight');
  } else if (validNumber(received)) {
    const variance = Math.abs(
      Number(loadedTons) - Number(received)
    );

    if (variance > SABIL_REVIEW_FLOW.allowedVarianceTons &&
        !String(remarks).trim()) {
      errors.push('Weight variance exceeds 1 tonne without explanation');
    }
  }

  if (errors.length) {
    decisionCell.setValue('Hold');
    reviewerCell.clearContent();
    reviewerCell.setNote(
      'Approval blocked:\n' + errors.join('\n')
    );

    SpreadsheetApp.getActiveSpreadsheet().toast(
      errors.join(' | '),
      'Approval blocked',
      8
    );
    return;
  }

  reviewerCell.clearNote();
  timeCell.setValue(new Date());
  timeCell.setNumberFormat('yyyy-mm-dd hh:mm:ss');
  decisionCell.setValue('Approved');

  console.log(JSON.stringify({
    event: 'TRIP_APPROVED',
    row: row,
    reviewer: reviewer,
    tripKey: tripKey
  }));
}
